/* ── Context ── */
interface I18nCtx { lang: Lang; setLang: (l: Lang) => void; t: (k: string) => string; isRTL: boolean; }
const Ctx = createContext<I18nCtx>({ lang: "ru", setLang: () => {}, t: k => k, isRTL: false });

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>("ru");
  useEffect(() => {
    try { const s = localStorage.getItem("pr-lang") as Lang; if (s && ALL_LANGS.includes(s)) setLangState(s); } catch {}
  }, []);
  useEffect(() => {
    try { localStorage.setItem("pr-lang", lang); } catch {}
    document.documentElement.lang = lang;
    document.documentElement.dir = RTL_LANGS.includes(lang) ? "rtl" : "ltr";
  }, [lang]);
  const setLang = useCallback((l: Lang) => setLangState(l), []);
  const t = useCallback((k: string) => T[lang]?.[k] ?? T.en?.[k] ?? k, [lang]);
  const isRTL = RTL_LANGS.includes(lang);
  return <Ctx.Provider value={{ lang, setLang, t, isRTL }}>{children}</Ctx.Provider>;
}

export function useLanguage() { return useContext(Ctx); }
